CREATE TABLE IF NOT EXISTS office_meetings(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('Ordinaria','Extraordinaria')),audience TEXT NOT NULL CHECK(audience IN ('Interna','Iglesias')),starts TEXT NOT NULL,location TEXT NOT NULL DEFAULT '',agenda TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Convocada',plan_year INTEGER NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS office_invites(meeting_id INTEGER NOT NULL REFERENCES office_meetings(id),group_id INTEGER NOT NULL REFERENCES groups(id),PRIMARY KEY(meeting_id,group_id));
CREATE TABLE IF NOT EXISTS office_minutes(meeting_id INTEGER PRIMARY KEY REFERENCES office_meetings(id),folio TEXT NOT NULL DEFAULT '',attendance TEXT NOT NULL DEFAULT '',summary TEXT NOT NULL DEFAULT '',agreements TEXT NOT NULL DEFAULT '',correspondence TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Borrador',updated_by INTEGER NOT NULL REFERENCES users(id),updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS office_campaigns(id INTEGER PRIMARY KEY,year INTEGER NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',deadline TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS office_plans(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),year INTEGER NOT NULL,title TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',updated TEXT NOT NULL,UNIQUE(group_id,year));
CREATE TABLE IF NOT EXISTS office_files(id INTEGER PRIMARY KEY,resource TEXT NOT NULL,resource_id INTEGER NOT NULL,group_id INTEGER NOT NULL REFERENCES groups(id),filename TEXT NOT NULL UNIQUE,original_name TEXT NOT NULL,mime TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS office_file_resource ON office_files(resource,resource_id,id);
CREATE TABLE IF NOT EXISTS office_plan_deliveries(id INTEGER PRIMARY KEY,campaign_id INTEGER NOT NULL REFERENCES office_campaigns(id),plan_id INTEGER NOT NULL REFERENCES office_plans(id),file_id INTEGER NOT NULL REFERENCES office_files(id),status TEXT NOT NULL DEFAULT 'Enviado',review_note TEXT NOT NULL DEFAULT '',sent_by INTEGER NOT NULL REFERENCES users(id),sent TEXT NOT NULL,reviewed_by INTEGER REFERENCES users(id),reviewed TEXT);
CREATE TABLE IF NOT EXISTS office_credentials(id INTEGER PRIMARY KEY,meeting_id INTEGER NOT NULL REFERENCES office_meetings(id),group_id INTEGER NOT NULL REFERENCES groups(id),attendees TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Enviada',review_note TEXT NOT NULL DEFAULT '',sent_by INTEGER NOT NULL REFERENCES users(id),sent TEXT NOT NULL,reviewed_by INTEGER REFERENCES users(id),reviewed TEXT,UNIQUE(meeting_id,group_id));
CREATE TABLE IF NOT EXISTS office_letters(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),direction TEXT NOT NULL CHECK(direction IN ('Recibida','Enviada')),number TEXT NOT NULL DEFAULT '',day TEXT NOT NULL,subject TEXT NOT NULL,counterparty TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',meeting_id INTEGER REFERENCES office_meetings(id),created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS office_templates(id INTEGER PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS finance_projects(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),name TEXT NOT NULL,event_id INTEGER REFERENCES records(id),UNIQUE(group_id,name));
CREATE TABLE IF NOT EXISTS finance_categories(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),name TEXT NOT NULL,UNIQUE(group_id,name));
CREATE TABLE IF NOT EXISTS finance_debts(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),kind TEXT NOT NULL CHECK(kind IN ('Por cobrar','Por pagar')),counterparty TEXT NOT NULL,description TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),day TEXT NOT NULL,due TEXT NOT NULL DEFAULT '',project_id INTEGER REFERENCES finance_projects(id),created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS finance_settlements(id INTEGER PRIMARY KEY,debt_id INTEGER NOT NULL REFERENCES finance_debts(id),record_id INTEGER NOT NULL UNIQUE REFERENCES records(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),voided INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS finance_tokens(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL);

CREATE UNIQUE INDEX IF NOT EXISTS office_unique_plan_copy ON office_plan_deliveries(campaign_id,plan_id,file_id);
